using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (only Person is included).
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata retrieval ──
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"TypeInfo<Person> obtained — Type: {personInfo.Type.Name}");

// Round-trip via the typed metadata to prove it works.
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Person p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"  Round-tripped: {p}");

// ── 2. Probe without throwing ──
// TryGetTypeInfo returns false instead of throwing when metadata isn't available.
// DefaultJsonTypeInfoResolver resolves any type, so use a custom resolver
// that only knows about Person to demonstrate a "miss".
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver())
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nTryGetTypeInfo(Person)  → found ({found!.Type.Name})");
else
    Console.WriteLine("\nTryGetTypeInfo(Person)  → not found");

if (limited.TryGetTypeInfo(typeof(Order), out _))
    Console.WriteLine("TryGetTypeInfo(Order)   → found");
else
    Console.WriteLine("TryGetTypeInfo(Order)   → not found (expected)");

// ── Types ──
record Person(string Name, int Age);
record Order(int Id, decimal Total);

// A resolver that only exposes Person metadata.
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}

